// The preset builder (with its live preview) is written ONCE, in the user app (frontend/src). The admin app uses copies so that admins
// build presets with exactly the same screen. This script runs before `npm run dev` / `npm run build` and refreshes the copies:
// admin/src/preset/*, admin/public/fonts, admin/public/preset-sample.mp4 (all git-ignored). Do not edit the copies.
import { cpSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const front = join(here, '..', '..', 'frontend');
const src = join(front, 'src');
const out = join(here, '..', 'src', 'preset');
if (!existsSync(src)) { console.error('sync-preset: frontend/src not found'); process.exit(1); }
mkdirSync(out, { recursive: true });
for (const f of ['PresetEditor.jsx', 'PreviewStudio.jsx', 'CaptionStyleControls.jsx', 'captionFonts.js', 'Select.jsx', 'voiceNames.js', 'safeArea.js']) {   // safeArea.js: imported by Select.jsx (menus stay clear of the status bar)
  let text = readFileSync(join(src, f), 'utf8');
  text = text.replace(/from '\.\/i18n\.jsx'/g, "from '../i18n.jsx'");   // the admin app has its own language provider with the same hook
  writeFileSync(join(out, f), `// GENERATED by scripts/sync-preset.mjs from frontend/src/${f}: do not edit here.\n${text}`);
}
mkdirSync(join(here, '..', 'public'), { recursive: true });
cpSync(join(front, 'public', 'fonts'), join(here, '..', 'public', 'fonts'), { recursive: true });
cpSync(join(front, 'public', 'preset-sample.mp4'), join(here, '..', 'public', 'preset-sample.mp4'));
console.log('sync-preset: copied the preset builder from the user app');
